-
-    // if readingChunks = false - just log response.
-    PrivateAccessor.setField(handler, "readingChunks", Boolean.FALSE);
-    handler.messageReceived(null, eventMock);
-
-    verify(eventMock, futureMock, chunkMock, bufferMock);
-  }
