+package com.couchbase.client.java.error;
+
+/**
+ * A RuntimeException being thrown whenever an operation on a {@link com.couchbase.client.java.Bucket Bucket}
+ * that has been {@link com.couchbase.client.java.Bucket#close() closed} is attempted.
+ */
+public class BucketClosedException extends RuntimeException {
+
+  public BucketClosedException() {
+  }
+
+  public BucketClosedException(String message) {
+    super(message);
+  }
+
+  public BucketClosedException(String message, Throwable cause) {
+    super(message, cause);
+  }
+}

