diff --git a/src/main/java/com/couchbase/client/java/repository/mapping/ReflectionBasedEntityProperties.java b/src/main/java/com/couchbase/client/java/repository/mapping/ReflectionBasedEntityProperties.java
new file mode 100644
index 0000000000000000000000000000000000000000..fcdb4577e7055f508038a3a6428e68a235b79418
