+
+    public IndexDoesNotExistException() {
+    }
+
+    public IndexDoesNotExistException(String message) {
+        super(message);
+    }
+
+    public IndexDoesNotExistException(String message, Throwable cause) {
+        super(message, cause);
+    }
+
+    public IndexDoesNotExistException(Throwable cause) {
+        super(cause);
+    }
+}
