+        element(new SelectElement(SelectType.DISTINCT, expressions));
+        return new DefaultFromPath(this);
+    }
+
+    @Override
+    public FromPath selectRaw(Expression expression) {
+        element(new SelectElement(SelectType.RAW, expression));
+        return new DefaultFromPath(this);
+    }
+}
