diff --git a/src/main/java/com/couchbase/client/java/query/dsl/path/AbstractPath.java b/src/main/java/com/couchbase/client/java/query/dsl/path/AbstractPath.java
new file mode 100644
index 0000000000000000000000000000000000000000..797ee39f5f01140a9bc25276a23c65e11fce7404
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/query/dsl/path/AbstractPath.java
@@ -0,0 +1,39 @@
+package com.couchbase.client.java.query.dsl.path;
+
+import com.couchbase.client.java.query.dsl.element.Element;
+
+/**
+ * .
+ *
+ * @author Michael Nitschinger
+ */
+public abstract class AbstractPath implements Path {
+
+    private Element element;
+    private AbstractPath parent;
+
+    protected AbstractPath(AbstractPath parent) {
+        this.parent = parent;
+    }
+
+    private String render() {
+        StringBuilder sb = new StringBuilder();
+        if (parent != null) {
+            sb.append(parent.render()).append(" ");
+        }
+        if (element != null) {
+            sb.append(element.export());
+        }
+        return sb.toString();
+    }
+
+    protected void element(Element element) {
+        this.element = element;
+    }
+
+    @Override
+    public String toString() {
+        return render().trim();
+    }
+
+}
