+package com.couchbase.client.vbucket.cccp;
+
+import net.spy.memcached.ops.Operation;
+import net.spy.memcached.ops.OperationCallback;
+
+
+public interface GetConfigOperation extends Operation {
+
+  /**
+   * Operation callback for the get config request.
+   */
+  interface Callback extends OperationCallback {
+
+    /**
+     * Callback for each result from a get.
+     *
+     * @param data the payload returned.
+     */
+    void gotData(byte[] data);
+  }
+
+}
diff --git a/src/main/java/com/couchbase/client/vbucket/cccp/GetConfigOperationImpl.java b/src/main/java/com/couchbase/client/vbucket/cccp/GetConfigOperationImpl.java
new file mode 100644
index 0000000000000000000000000000000000000000..83074458c7d142d7148763916ef6386dc619af06
--- /dev/null
+++ b/src/main/java/com/couchbase/client/vbucket/cccp/GetConfigOperationImpl.java
@@ -0,0 +1,35 @@
+package com.couchbase.client.vbucket.cccp;
+
+import net.spy.memcached.ops.OperationCallback;
+import net.spy.memcached.protocol.binary.OperationImpl;
+
+
+public class GetConfigOperationImpl extends OperationImpl
+  implements GetConfigOperation {
+
+  /**
+   * Represents the CMD_GET_CLUSTER_CONFIG command.
+   */
+  private static final byte CMD = (byte) 0xb5;
+
+  /**
+   * No need for opaque here.
+   */
+  private static final int OPAQUE = 0;
+
+  public GetConfigOperationImpl(OperationCallback callback) {
+    super(CMD, OPAQUE, callback);
+  }
+
+  @Override
+  public void initialize() {
+    prepareBuffer("", 0, EMPTY_BYTES);
+  }
+
+  @Override
+  protected void decodePayload(byte[] pl) {
+    GetConfigOperation.Callback gcb = (GetConfigOperation.Callback) getCallback();
+    gcb.gotData(pl);
+    getCallback().receivedStatus(STATUS_OK);
+  }
+}
