diff --git a/src/main/java/com/couchbase/client/java/util/OnSubscribeDeferAndWatch.java b/src/main/java/com/couchbase/client/java/util/OnSubscribeDeferAndWatch.java
new file mode 100644
index 0000000000000000000000000000000000000000..8bc3045bdc76724c87cbe42c9859e8e6f5b6c41c
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/util/OnSubscribeDeferAndWatch.java
@@ -0,0 +1,130 @@
+/*
+ * Copyright (c) 2016 Couchbase, Inc.
+ *
+ * Licensed under the Apache License, Version 2.0 (the "License");
+ * you may not use this file except in compliance with the License.
+ * You may obtain a copy of the License at
+ *
+ *    http://www.apache.org/licenses/LICENSE-2.0
