index 0000000000000000000000000000000000000000..be07a4a7a7f25df397dfc2ce84f8a16832f9ed72
--- /dev/null
+++ b/src/test/java/com/couchbase/client/NettyViewConnectionTest.java
@@ -0,0 +1,140 @@
+/**
