-     * @return true if successful
-     */
-    public Boolean add(final String key, final V value, final MutationOptionBuilder mutationOptionBuilder) {
-        return this.bucket.mapAdd(this.docId, key, value, mutationOptionBuilder);
-    }
-
-    /**
