index 0000000000000000000000000000000000000000..61ca35477466a61daa2d2b9bf1ae788bb4922b7f
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/query/core/Criteria.java
@@ -0,0 +1,146 @@
