+package com.couchbase.client.java.query.core;
+
+/**
+ * Short description of class
+ *
+ * @author Simon Baslé
+ * @since X.X
+ */
+public enum Operator {
+    EQUALS,
+    GREATER_THAN, LESSER_THAN,
+    GREATER_THAN_EQUALS, LESSER_THAN_EQUALS,
+    LIKE, CONTAINS,
+    IS_NULL, IS_MISSING, IS_VALUED,
