index 0000000000000000000000000000000000000000..2700241e3361d380ff4ae57c72c8741b23714fa9
--- /dev/null
+++ b/src/main/java/com/couchbase/client/internal/ReplicaGetFuture.java
@@ -0,0 +1,111 @@
