new file mode 100644
index 0000000000000000000000000000000000000000..e28ebca9d134bd1bee655228631442f247de9f89
--- /dev/null
+++ b/src/test/java/com/couchbase/client/java/transcoder/BigDecimalExactConversionTest.java
@@ -0,0 +1,84 @@
+/*
+ * Copyright (c) 2016 Couchbase, Inc.
