+
+        bucket().upsert(JsonDocument.create("bigDecimalDoc", original));
+
+        RawJsonDocument rawLoaded = bucket().get("bigDecimalDoc", RawJsonDocument.class);
+        assertEquals("{\"value\":12345.678901234567890432423432324}", rawLoaded.content());
+
