diff --git a/src/main/java/com/couchbase/client/java/document/ByteArrayDocument.java b/src/main/java/com/couchbase/client/java/document/ByteArrayDocument.java
new file mode 100644
index 0000000000000000000000000000000000000000..20413c04a8153ba2929a7fcb7c081f3739c17101
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/document/ByteArrayDocument.java
@@ -0,0 +1,161 @@
+/*
+ * Copyright (c) 2017 Couchbase, Inc.
+ *
+ * Licensed under the Apache License, Version 2.0 (the "License");
+ * you may not use this file except in compliance with the License.
+ * You may obtain a copy of the License at
+ *
+ *    http://www.apache.org/licenses/LICENSE-2.0
